'use strict';
(() => {
const C=ClarityCore,S=ClarityStore,$=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={shield:'M12 3 20 6v6c0 5-8 9-8 9s-8-4-8-9V6Z M8.5 12l2.5 2.5 4.5-5',chat:'M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2v-10A8.5 8.5 0 0 1 10.5 3H13a8 8 0 0 1 8 8.5Z',plus:'M12 5v14M5 12h14',menu:'M4 6h16M4 12h16M4 18h16',close:'m6 6 12 12M18 6 6 18',arrow:'M12 19V5m-6 6 6-6 6 6',back:'m10 5-7 7 7 7M3 12h18',chevron:'m9 5 7 7-7 7',lock:'M6 10h12v11H6ZM8 10V7a4 4 0 0 1 8 0v3m-4 5v2',info:'M12 17v-5m0-4v.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'m5 12 4 4L19 6',warning:'m12 3 10 18H2ZM12 9v5m0 3v.01',settings:'M4 7h16M4 17h16M8 4v6m8 4v6',help:'M9.5 8a2.6 2.6 0 1 1 4.5 2c-1.5 1-2 1.5-2 3m0 4v.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',undo:'M3 4v6h6M3 10a8 8 0 1 1 1 8',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Zm5 12 6 6',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',location:'M12 22s8-8 8-13a8 8 0 0 0-16 0c0 5 8 13 8 13ZM12 6a3 3 0 1 0 0 6 3 3 0 0 0 0-6',code:'m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18',edit:'m15 4 5 5M4 15 16 3l5 5L9 20l-6 1Z',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',history:'M3 3v6h6M3 9a9 9 0 1 1 0 6m9-9v6l4 2',external:'M14 3h7v7m0-7L10 14M9 3H3v18h18v-6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7ZM12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',moon:'M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8Z',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10ZM12 1v2m0 18v2M4.2 4.2l1.4 1.4m12.8 12.8 1.4 1.4M1 12h2m18 0h2M4.2 19.8l1.4-1.4M18.4 5.6l1.4-1.4'};
const icon=(n,cl='')=>`<svg class="icon ${cl}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.info}"/></svg>`;
const button=(label,action,cl='',attrs='')=>`<button type="button" class="btn ${cl}" data-action="${action}" ${attrs}>${label}</button>`;
let state=S.state(),route='chat',selected=null,reviewOpen=false,sidebarOpen=false,filter='all',search='',prefsDraft=null,composing=false,lastTyping=0,modalReturn=null,toastTimer,typingTimer,lastCount=-1;
const chat=()=>state.chats.find(c=>c.id===state.currentChat)||state.chats[0];
const save=()=>S.saveState(state);
const issues=()=>C.detect(chat().draft,state.prefs.categories);
const pending=()=>issues().filter(f=>!chat().kept.includes(f.id));
const condition=()=>S.study().active?.condition||'inline';
const activeTrial=()=>S.study().active;
const reuseLabels={ask:'Ask before reuse',auto:'Reuse automatically',current:'This chat only',never:'Do not reuse',default:'Follow default'};
const groupLabels={shared:'Shared in chats',preferences:'Saved preferences',inferences:'Possible inferences'};
const routes=[['chat','chat','Chat'],['dashboard','shield','Privacy dashboard'],['preferences','settings','Privacy preferences'],['help','help','Help & about']];
const brand=()=>`<a class="brand" href="#chat" aria-label="Clarity chat"><span class="brand-mark">${icon('shield')}</span><span><span class="brand-word">Clarity</span><div class="mini">YOUR WORDS. YOUR CHOICE.</div></span></a>`;
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
function announce(text){$('#announcer').textContent='';setTimeout(()=>$('#announcer').textContent=text,25);}
function toast(text,action,label){clearTimeout(toastTimer);$('#toast').innerHTML=`${icon('check')}<span>${esc(text)}</span>${action?button(label,action,'compact'):''}<button class="icon-btn" data-action="dismiss-toast" aria-label="Dismiss notification">${icon('close')}</button>`;$('#toast').classList.remove('leaving');$('#toast').hidden=false;toastTimer=setTimeout(hideToast,10000);}
function hideToast(){const t=$('#toast');clearTimeout(toastTimer);if(t.hidden)return;if(reduced()){t.hidden=true;return;}t.classList.add('leaving');toastTimer=setTimeout(()=>{t.hidden=true;t.classList.remove('leaving');},160);}
let modalCloseTimer;
function modal(title,body,actions,focus){const m=$('#modal');if(m.classList.contains('closing')){clearTimeout(modalCloseTimer);m.classList.remove('closing');}else modalReturn=document.activeElement;$('#modal').innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-content">${body}</div><div class="modal-actions">${actions}</div>`;if(!$('#modal').open)$('#modal').showModal();setTimeout(()=>{const target=focus?$(focus):$('#modal [data-action="close-modal"]');target?.focus();},0);}
function closeModal(){const m=$('#modal'),old=modalReturn;const refocus=()=>{if(old?.isConnected)old.focus();else ($('#main h1')||$('#review-button')||$('#main'))?.focus();};if(!m.open||reduced()){if(m.open)m.close();setTimeout(refocus,0);return;}if(m.classList.contains('closing'))return;m.classList.add('closing');clearTimeout(modalCloseTimer);modalCloseTimer=setTimeout(()=>{m.classList.remove('closing');m.close();refocus();},150);}
function setSidebar(open){sidebarOpen=open;const nav=$('#navigation');if(!nav)return;nav.classList.toggle('open',open);nav.inert=!open;$('.sidebar-scrim')?.classList.toggle('open',open);$('.mobile-menu')?.setAttribute('aria-expanded',open);}
const THEME_KEY='clarity.theme',isDark=()=>document.documentElement.dataset.theme==='dark';
function themeToggle(){const d=isDark();return `<button type="button" class="theme-toggle" data-action="toggle-theme" aria-pressed="${d}">${icon(d?'moon':'sun')}<span>Dark mode</span><span class="switch" aria-hidden="true"></span></button>`;}
function setTheme(dark,remember=true){const h=document.documentElement;if(!reduced()){h.classList.add('theme-switching');clearTimeout(setTheme.t);setTheme.t=setTimeout(()=>h.classList.remove('theme-switching'),320);}if(dark)h.dataset.theme='dark';else delete h.dataset.theme;if(remember){try{localStorage.setItem(THEME_KEY,dark?'dark':'light');}catch{}}document.querySelector('meta[name=theme-color]')?.setAttribute('content',dark?'#121614':'#f7f7fa');const b=$('.theme-toggle');if(b)b.outerHTML=themeToggle();}
function navigate(next){if(route==='preferences'&&prefsDraft){state.prefsDraft=prefsDraft;save();}selected=null;reviewOpen=false;sidebarOpen=false;if(location.hash==='#'+next)render();else location.hash=next;}
function shell(content){const names={chat:'Chat',dashboard:'Privacy dashboard',preferences:'Privacy preferences',help:'Help & about'};const a=activeTrial();return `<div class="app-shell"><button class="sidebar-scrim ${sidebarOpen?'open':''}" data-action="close-menu" aria-label="Close menu"></button><aside id="navigation" class="sidebar ${sidebarOpen?'open':''}" ${sidebarOpen?'':'inert'}>${brand()}${button(icon('plus')+'New chat','new-chat','new-chat')}<nav class="sidebar-section" aria-label="Main navigation"><div class="eyebrow">Workspace</div>${routes.map(([r,i,t])=>`<a href="#${r}" class="nav-link ${route===r?'active':''}" ${route===r?'aria-current="page"':''}>${icon(i)}${t}${r==='dashboard'?`<span class="nav-count">${state.items.length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-section"><div class="eyebrow">Conversations</div>${state.chats.slice(0,7).map(c=>`<div class="chat-row"><button class="nav-link chat-link ${route==='chat'&&c.id===chat().id?'active':''}" data-action="open-chat" data-id="${esc(c.id)}">${esc(c.title)}</button><button type="button" class="icon-btn chat-delete" data-action="delete-chat" data-id="${esc(c.id)}" aria-label="Delete conversation: ${esc(c.title)}" title="Delete conversation">${icon('trash')}</button></div>`).join('')}</div><div class="sidebar-bottom">${themeToggle()}<div class="local-note"><strong>${icon('lock','small')}Stored in this browser</strong>Fictional examples. Scripted responses. Your prototype data stays on this device.</div><div class="profile-row"><span class="avatar">C</span><div>Prototype workspace<br><small class="muted">INF2002 · Team 08</small></div></div></div></aside><div class="main-wrap"><header class="topbar"><div class="topbar-left"><button class="icon-btn mobile-menu" data-action="toggle-menu" aria-label="Open navigation menu" aria-expanded="${sidebarOpen}" aria-controls="navigation">${icon('menu')}</button><div><div class="topbar-title">${names[route]}<span class="prototype-badge">Prototype</span></div><div class="topbar-sub">Clarity · Privacy assistant</div></div></div></header>${a?`<div class="research-session-strip"><span>${a.startedAt?'Study task in progress · local interaction recording':'Study task ready · fictional information only'}</span>${button(a.startedAt?'Finish task':'Begin task',a.startedAt?'finish-task':'begin-task','compact')}</div>`:''}${S.storageProblem?'<div class="storage-warning" role="alert">Browser storage is unavailable or invalid. Changes may last only for this tab; study export and cross-tab controls may be unavailable.</div>':''}${content}</div></div>`;}
function chatView(){const c=chat();return `<main id="main" tabindex="-1" class="chat-layout"><div class="chat-main"><section class="conversation" aria-label="Conversation"><div class="messages">${c.messages.length?`<div class="chat-date">${c.id==='chat-weekend'?'Fictional sample conversation':'This conversation stays in your browser'}</div>${c.messages.map(m=>`<article class="message ${m.role}">${m.role==='assistant'?`<div class="message-avatar">${icon('spark')}</div>`:''}<div class="message-body"><div class="message-label">${m.role==='assistant'?'Clarity <span>Scripted response</span>':'You'}</div><div class="message-text">${esc(m.text)}</div></div></article>`).join('')}`:`<div class="welcome"><div class="welcome-symbol">${icon('chat')}</div><h1>What’s on your mind?</h1><p>Write naturally. Choose what you share.</p><div class="suggestions" aria-label="Fictional example prompts">${[['maskA','code','Debug an error','Get help without sharing a key'],['retain','location','Find a place nearby','Keep the context that matters'],['multiple','edit','Draft a message','Review names and contact details']].map(([id,i,t,s])=>`<button class="suggestion" data-action="example" data-id="${id}">${icon(i)}<strong>${t}</strong><span>${s}</span></button>`).join('')}</div><div class="example-label">${icon('info','small')}Try a fictional example, or write your own prompt.</div></div>`}</div></section><section class="composer-region" aria-label="Write and review your prompt"><aside class="review-aside ${reviewOpen?'is-open':''}" id="privacy-review" aria-label="Privacy review"></aside><div class="composer-box"><label id="composer-label" class="composer-label"><span>Your prompt</span><span>Only shared when you send</span></label><div id="composer" class="composer" contenteditable="true" role="textbox" aria-multiline="true" aria-labelledby="composer-label" aria-describedby="composer-guidance" data-placeholder="Message Clarity…" spellcheck="false"></div><div class="composer-footer"><div id="composer-feedback"></div>${button('Send '+icon('arrow','small'),'send','primary send-btn','id="send-button" title="Send (Ctrl+Enter)" aria-keyshortcuts="Control+Enter Meta+Enter"')}</div></div><div id="undo-controls"></div><div class="composer-bottom" id="composer-guidance"><span>Demo detection can miss details. <a href="#help">How it works</a></span><span class="keyboard-hint">Enter for a new line · Ctrl/⌘ Enter to send</span></div></section></div></main>`;}
function renderComposer(restore=false){const el=$('#composer');if(!el)return;const saved=restore?selectionOffsets(el):null;const c=chat(),flags=issues();let html='',at=0;if(condition()==='inline'){for(const f of flags){html+=esc(c.draft.slice(at,f.start));html+=`<span class="flag ${c.kept.includes(f.id)?'kept':''} ${selected===f.id?'selected':''}" data-flag="${f.id}" role="button" tabindex="0" aria-label="Review ${esc(C.categories[f.category].singular)}${c.kept.includes(f.id)?', kept unchanged':''}">${esc(f.value)}</span>`;at=f.end;}html+=esc(c.draft.slice(at));}else html=esc(c.draft);el.innerHTML=html+(c.draft.endsWith('\n')?'<br data-caret-sentinel="true">':'');if(saved)restoreSelection(el,saved);renderFeedback();renderReview();}
function renderFeedback(){if(!$('#composer-feedback'))return;const all=issues(),left=pending();$('#composer-feedback').innerHTML=all.length?`<button id="review-button" type="button" class="review-trigger" data-action="review">${icon(left.length?'warning':'check')}<span>${left.length?`${left.length} detail${left.length===1?'':'s'} to review`:`${all.length} detail${all.length===1?'':'s'} kept unchanged`} · Review</span></button>`:`<span class="composer-status">${icon('shield')}<span>${chat().draft?'No matches found · review your wording':'Privacy check is ready'}</span></span>`;$('#send-button').disabled=!chat().draft.trim();$('#undo-controls').innerHTML=chat().undo.length||chat().redo.length?`<div class="undo-row">${button(icon('undo','small')+(chat().undo.at(-1)?.label||'Undo change'),'undo','ghost compact',chat().undo.length?'':'disabled')}${chat().redo.length?button('Redo','redo','ghost compact'):''}<span>Changes stay in your draft until you send.</span></div>`:'';if(left.length!==lastCount){lastCount=left.length;clearTimeout(typingTimer);typingTimer=setTimeout(()=>announce(left.length?`${left.length} potentially sensitive details. Use Review near Send to inspect them.`:'No unreviewed matches. Detection is limited.'),550);}}
function renderReview(){const el=$('#privacy-review');if(!el)return;if(reviewOpen&&!el.classList.contains('is-open')&&!reduced()){el.classList.add('entering');setTimeout(()=>el.classList.remove('entering'),300);}el.classList.toggle('is-open',reviewOpen);if(!reviewOpen){el.innerHTML='';return;}const all=issues();let f=all.find(f=>f.id===selected)||all.find(f=>!chat().kept.includes(f.id))||all[0];selected=f?.id;const left=pending();if(!f){el.innerHTML=`<div class="review-heading"><h2 tabindex="-1">Review complete</h2><button class="icon-btn" data-action="close-review" aria-label="Close privacy review">${icon('close')}</button></div><p class="aside-description">Your draft has no remaining matches. Check the wording before sending; this demo cannot detect every sensitive detail.</p>${button('Return to prompt','edit-draft','primary')}`;return;}const meta=C.categories[f.category],kept=chat().kept.includes(f.id);el.innerHTML=`<div class="review-heading"><h2 id="review-title" tabindex="-1">Review before sharing</h2><button class="icon-btn" data-action="close-review" aria-label="Close privacy review">${icon('close')}</button></div>${all.length>1?`<div class="issue-tabs" aria-label="Flagged details">${all.map((x,i)=>`<button class="issue-tab ${x.id===f.id?'active':''}" data-action="select-issue" data-id="${x.id}" aria-pressed="${x.id===f.id}">${i+1}. ${esc(C.categories[x.category].singular)}${chat().kept.includes(x.id)?' · kept':''}</button>`).join('')}</div>`:''}<div class="review-card"><div class="review-copy"><span class="badge ${kept?'purple':'amber'}">${icon(kept?'check':'warning','small')}${kept?'Kept unchanged':esc(meta.singular)}</span><h3>${kept?'You chose to share this detail':'Is this detail needed for your request?'}</h3><p>${esc(meta.reason)}</p><details class="review-details"><summary>Why this matters & what to keep</summary><p>${esc(meta.context)}</p><p>Only your draft changes when you mask. This is a rule-based demonstration, not a security guarantee.</p></details></div><div class="review-choice"><div class="comparison"><div><span class="comparison-label">Original information</span><div class="comparison-value original">${esc(f.value)}</div></div><div><span class="comparison-label">Suggested replacement</span><div class="comparison-value replacement">${esc(f.replacement)}</div></div></div><div class="review-actions">${button('Mask information','mask','primary',`data-id="${f.id}"`)}${f.generalised?button('Generalise to “'+esc(f.generalised)+'”','generalise','',`data-id="${f.id}"`):''}${button(kept?'Review this decision':'Keep unchanged',kept?'unkeep':'keep','',`data-id="${f.id}"`)}${button('Edit manually','edit-draft','ghost')}</div></div></div>${left.length>1?`<div class="batch-area"><p>${left.length} details still need a decision. You can review replacements together.</p>${button('Review multiple changes','batch','compact')}</div>`:''}`;}
function dashboardView(){return `<main id="main" tabindex="-1" class="page"><div class="page-heading"><div><div class="eyebrow">Your information, in view</div><h1 tabindex="-1">Privacy dashboard</h1><p>Review what this demo remembers about you and choose how it can be used.</p></div><a href="#preferences" class="btn">${icon('settings')}Privacy preferences</a></div><div class="info-banner">${icon('info')}<span><strong>Simulated profile, stored in this browser.</strong> Entries come from fictional examples and details you send in this prototype. It cannot read or delete actual GPT data.</span></div><div class="toolbar"><div class="search-box">${icon('search')}<label class="sr-only" for="memory-search">Search your information</label><input id="memory-search" type="search" placeholder="Search your information…" value="${esc(search)}"></div><div class="tabs" aria-label="Information categories">${[['all','All information'],['shared','Shared in chats'],['preferences','Saved preferences'],['inferences','Possible inferences'],['removed','Removed']].map(([id,label])=>`<button class="tab ${filter===id?'active':''}" data-action="filter" data-id="${id}" aria-pressed="${filter===id}">${label}<span class="tab-count">${id==='all'?state.items.length:id==='removed'?state.removed.length:state.items.filter(x=>x.group===id).length}</span></button>`).join('')}<span class="tab-indicator" aria-hidden="true"></span></div></div><div id="memory-results"></div><p class="preferences-note">Removing a profile item stops its simulated future reuse. The original conversation stays in your chat history. <a href="#help">Understand these controls</a></p></main>`;}
function renderMemory(animate){const el=$('#memory-results');if(!el)return;const h0=el.offsetHeight;const removed=filter==='removed';const list=(removed?state.removed:state.items).filter(x=>(filter==='all'||removed||x.group===filter)&&`${x.label} ${x.value} ${x.source}`.toLowerCase().includes(search.toLowerCase()));el.innerHTML=`${removed?'<div class="info-banner neutral">Removed items remain locally recoverable until you delete them permanently. They are excluded from simulated reuse.</div>':''}<div class="memory-list">${list.length?list.map(x=>`<article class="memory-card"><div class="memory-symbol">${icon(x.category==='location'?'location':x.group==='preferences'?'settings':x.group==='inferences'?'spark':'lock')}</div><div><div class="memory-group">${esc(groupLabels[x.group])}</div><h3>${esc(x.value)}</h3><p>${esc(x.label)}</p>${x.group==='inferences'?'<div class="inference-note">Unconfirmed example · may be wrong</div>':''}<div class="memory-meta"><span class="badge ${removed?'':'purple'}">${removed?'Excluded from reuse':esc(reuseLabels[x.reuse])}</span><span class="muted">·</span>${x.chatId&&state.chats.some(c=>c.id===x.chatId)?`<button class="source-btn" data-action="source" data-id="${esc(x.chatId)}">From: ${esc(x.source)}</button>`:`<span class="muted"><small>${esc(x.source)}</small></span>`}</div></div><div class="memory-actions">${removed?`${button('Restore','restore','compact',`data-id="${x.id}"`)}${button('Delete permanently','permanent','text-danger compact',`data-id="${x.id}"`)}`:`${button('More details','memory-details','compact',`data-id="${x.id}"`)}<button class="icon-btn delete-icon" data-action="delete-item" data-id="${x.id}" aria-label="Delete ${esc(x.label)}">${icon('trash')}</button>`}</div></article>`).join(''):`<div class="empty-state">${icon(removed?'trash':'search')}<h3>${search?'No matching information':removed?'No removed items':'Nothing in this category yet'}</h3><p>${search?'Try a different word or clear the search.':'Your profile updates when you send detected details in a demo chat.'}</p></div>`}</div>`;if(animate&&!reduced())animateList(el,h0);}
function radio(name,value,title,description,chosen){return `<label class="radio-card"><input type="radio" name="${name}" value="${value}" ${chosen===value?'checked':''}><span><strong>${title}</strong><small>${description}</small></span></label>`;}
function preferencesView(){prefsDraft=prefsDraft||state.prefsDraft||C.clone(state.prefs);const p=prefsDraft;return `<main id="main" tabindex="-1" class="page"><div class="page-heading"><div><div class="eyebrow">Make it work for you</div><h1 tabindex="-1">Privacy preferences</h1><p>Choose how much guidance you want and what can be reused in this demo.</p></div></div><form id="preferences-form"><section class="setting-card"><h2>When should Clarity get your attention?</h2><p>Suggestions never change your words automatically.</p><div class="option-grid">${radio('warningMode','notice','A gentle notice','Show a warning while I write. Let me send without an extra confirmation.',p.warningMode)}${radio('warningMode','pause','Pause before sending','Ask me to review unaddressed details before the prompt is sent.',p.warningMode)}</div></section><section class="setting-card"><h2>What should the demo check?</h2><p>Turn categories on or off. These simple patterns cover selected examples, not every possible detail.</p><div class="check-list">${Object.entries(C.categories).map(([key,meta])=>`<label class="check-row"><input type="checkbox" name="category" value="${key}" ${p.categories[key]?'checked':''}>${esc(meta.label)}</label>`).join('')}</div></section><section class="setting-card"><h2>Using information in another conversation</h2><p>This default applies to profile entries set to “Follow default.” Individual choices in the dashboard take priority.</p><div class="option-grid">${radio('reuseMode','ask','Ask before each reuse','Show me which detail will be used, and let me decide.',p.reuseMode)}${radio('reuseMode','selected','Only details I have approved','Use items marked “Reuse automatically”; skip all others.',p.reuseMode)}${radio('reuseMode','current','Use this chat only','Do not reuse default-controlled items in other conversations.',p.reuseMode)}${radio('reuseMode','auto','Reuse relevant information','Allow default-controlled items in the scripted reuse example.',p.reuseMode)}</div><p class="preferences-note">The reuse example makes these controls visible. Normal chat replies are scripted and do not use a real memory system.</p><div class="research-actions">${button('Try the reuse example','reuse-demo','')}${button('Apply this default to existing items','apply-default','ghost')}</div></section><section class="setting-card"><h2>How should details look?</h2><p>Stronger cues use thicker underlines and borders, so nothing depends on colour alone.</p><div class="option-grid">${radio('display','standard','Standard','Coloured highlights with wavy and dotted underlines.',p.display||'standard')}${radio('display','strong','Stronger visual cues','Thicker underlines, bolder borders and outlines. Helpful for colour-vision differences or low vision.',p.display||'standard')}</div></section><div class="save-bar"><p id="preference-save-status">Changes take effect when you save.</p><button type="submit" class="btn primary">Save preferences</button></div></form></main>`;}
function helpView(){return `<main id="main" tabindex="-1" class="page"><div class="page-heading"><div><div class="eyebrow">A little clarity</div><h1 tabindex="-1">You decide what to share.</h1><p>A guide to the privacy assistant and the boundaries of this prototype.</p></div></div><div class="help-grid"><section class="help-card">${icon('edit')}<h2>Review as you write</h2><p>Selected patterns are marked with a squiggly underline. Select a marked detail, or choose Review near Send. Compare the original with the suggestion, then mask, generalise, edit manually, or keep unchanged.</p><p>“Keep unchanged” applies to that occurrence in the current draft. Editing its text triggers a new check. Replacements stay editable.</p><div class="flow"><span>Write</span>→<span>Review</span>→<span>Choose</span>→<span>Send</span></div></section><section class="help-card">${icon('undo')}<h2>Change your mind</h2><p>Undo restores a draft change, including masking or a keep decision. You can undo several changes before sending. Sending clears draft undo history; it does not delete the conversation.</p><p>Opening the dashboard, preferences, or help keeps your draft and conversation. Each conversation has its own draft.</p></section><section class="help-card">${icon('shield')}<h2>What the dashboard means</h2><ul><li><strong>Shared in chats:</strong> selected details found in prompts sent in this prototype.</li><li><strong>Saved preferences:</strong> fictional examples intentionally stored for personalisation.</li><li><strong>Possible inferences:</strong> prewritten, unconfirmed examples. They may be wrong; no traits are inferred from your text.</li></ul></section><section class="help-card">${icon('trash')}<h2>What deletion changes</h2><p>Delete moves a profile item to Removed and excludes it from simulated reuse. The original message, chat history, and anonymous study events remain. Restore brings the profile item back.</p><p>“Delete permanently” erases the recoverable profile copy from this browser’s prototype storage; it still does not remove text in conversations. It cannot affect actual GPT accounts, servers, or data.</p></section><section class="help-card wide">${icon('info')}<h2>A simulation with clear limits</h2><p>There is no GPT connection, backend, account, API key, extension, or upload scanner. Replies are fixed scripts for debugging, local planning, and writing; fictional restaurant names are not real recommendations. Detection runs locally using regular expressions and a small example vocabulary.</p><details><summary>What can it detect, and what can it miss?</summary><p>Examples include labelled API keys/passwords, sk- sample keys, email addresses, Singapore-style phone and ID numbers, 16-digit numbers, selected Singapore neighbourhoods, selected English name patterns, and a few health terms. It can flag harmless text and miss sensitive details, unfamiliar formats, indirect references, combinations of details, other languages, and all content in images or documents. “No matches” does not mean a prompt is safe. Category preferences can suppress warnings.</p></details><details><summary>Where is information stored?</summary><p>Drafts, sent messages, profile items, removed items, and preferences are saved in this browser’s local storage for this site. Reloading normally restores them. They are not encrypted. Use fictional details on shared devices. Clearing browser site data removes this local copy. Opening the local files and the hosted site creates separate stores.</p><p>Research recording is off by default. After consent, a prepared study records an anonymous participant code, assigned condition, task timing and interaction metadata. It does not record prompt text, detected values, message content, or profile values in the event export. Conversation text still remains separately in local prototype storage. Exported files remain wherever the researcher saved them.</p></details><details><summary>How does simulated reuse work?</summary><p>The dashboard offers per-item rules. In Preferences, save your default and try the reuse example. “Ask” requests permission for that single example, “This chat only” skips reuse, and “Reuse automatically” includes the selected value in a labelled scripted preview. Removed items cannot be selected. The preview does not connect to a model or rewrite previous messages.</p></details></section><section class="help-card wide">${icon('settings')}<h2>Keyboard & accessibility</h2><p>Use <kbd class="kbd">Tab</kbd> to move between controls and <kbd class="kbd">Enter</kbd> to activate a focused flagged detail. The Review button offers the same controls without selecting text. Use <kbd class="kbd">Ctrl/⌘ + Enter</kbd> to send, <kbd class="kbd">Alt + R</kbd> to review, <kbd class="kbd">Ctrl/⌘ + Z</kbd> to undo in the composer, and <kbd class="kbd">Esc</kbd> to close a panel or dialog. Enter inserts a new line while typing. Alerts use text and symbols as well as colour. For thicker underlines and borders, turn on Stronger visual cues in Privacy preferences.</p></section></div><a class="footer-link" href="researcher.html" target="_blank" rel="noopener">For researchers: open the separate study console ${icon('external','small')}</a></main>`;}
function applyDisplay(mode){document.documentElement.classList.toggle('cues-strong',mode==='strong');}
let lastRoute=null;
function render(){route=location.hash.slice(1)||'chat';if(!['chat','dashboard','preferences','help'].includes(route))route='chat';const routeChanged=route!==lastRoute;lastRoute=route;applyDisplay(route==='preferences'&&prefsDraft?prefsDraft.display:state.prefs.display);document.title=`${route==='chat'?'Chat':route==='dashboard'?'Privacy dashboard':route==='preferences'?'Privacy preferences':'Help'} · Clarity`;$('#app').innerHTML=shell(route==='chat'?chatView():route==='dashboard'?dashboardView():route==='preferences'?preferencesView():helpView());if(routeChanged&&!reduced())$('#main')?.classList.add('route-enter');if(route==='chat'){renderComposer();bindComposer();}if(route==='dashboard'){renderMemory();placeIndicator(true);}if(route==='preferences')bindPreferences();renderWidget();const a=activeTrial();$('#nav-widget').inert=!!(a&&!a.startedAt);if(a&&!a.startedAt){$('#main').inert=true;$('.topbar').inert=true;$('#navigation').inert=true;}}
const WIDGET_KEY='clarity.navWidgetPos',FAB=52,EDGE=12;let widgetOpen=false,widgetPos=null,drag=null,dragFrame=0;
function renderWidget(){const w=$('#nav-widget');w.innerHTML=`<button type="button" class="nav-fab" aria-haspopup="menu" aria-expanded="${widgetOpen}" aria-controls="nav-widget-menu" aria-label="Open Clarity navigation" title="Navigation · drag to move (Alt+arrow keys)">${icon('shield')}${state.items.length?`<span class="nav-fab-count" aria-hidden="true">${state.items.length}</span>`:''}</button><div id="nav-widget-menu" class="nav-widget-menu ${widgetOpen?'open':''}" role="menu" aria-label="Clarity navigation">${routes.filter(([r])=>r!==route).map(([r,i,t])=>`<a role="menuitem" tabindex="-1" href="#${r}" class="nav-link">${icon(i)}${t}${r==='dashboard'?`<span class="nav-count">${state.items.length}</span>`:''}</a>`).join('')}</div>`;w.classList.toggle('is-open',widgetOpen);placeWidget();}
function clampPos(p){return{x:Math.min(Math.max(EDGE,p.x),innerWidth-FAB-EDGE),y:Math.min(Math.max(EDGE,p.y),innerHeight-FAB-EDGE)};}
function placeWidget(){const w=$('#nav-widget');if(!widgetPos){try{widgetPos=JSON.parse(localStorage.getItem(WIDGET_KEY));}catch{}if(!widgetPos||!isFinite(widgetPos.x)||!isFinite(widgetPos.y))widgetPos={x:innerWidth-FAB-(innerWidth<=700?EDGE:24),y:innerHeight-FAB-(innerWidth<=700?250:140)};}widgetPos=clampPos(widgetPos);w.style.transform=`translate3d(${widgetPos.x}px,${widgetPos.y}px,0)`;w.classList.toggle('menu-left',widgetPos.x+FAB/2>innerWidth/2);w.classList.toggle('menu-up',widgetPos.y+FAB/2>innerHeight/2);}
function saveWidgetPos(){try{localStorage.setItem(WIDGET_KEY,JSON.stringify(widgetPos));}catch{}}
function setWidgetOpen(open,focusFirst){widgetOpen=open;const m=$('#nav-widget-menu'),f=$('.nav-fab');if(!m)return;m.classList.toggle('open',open);$('#nav-widget').classList.toggle('is-open',open);f.setAttribute('aria-expanded',open);if(open&&focusFirst)m.querySelector('[role=menuitem]')?.focus();}
function selectionOffsets(el){const sel=window.getSelection();if(!sel.rangeCount||!el.contains(sel.anchorNode))return null;const range=sel.getRangeAt(0);let a=document.createRange(),b=document.createRange();a.selectNodeContents(el);a.setEnd(range.startContainer,range.startOffset);b.selectNodeContents(el);b.setEnd(range.endContainer,range.endOffset);return [a.toString().length,b.toString().length];}
function restoreSelection(el,offsets){const w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT),nodes=[];while(w.nextNode())nodes.push(w.currentNode);if(!nodes.length){el.focus();return;}function point(n){let left=n;for(const node of nodes){if(left<=node.length)return[node,left];left-=node.length;}return[nodes.at(-1),nodes.at(-1).length];}const r=document.createRange(),a=point(offsets[0]),b=point(offsets[1]);r.setStart(...a);r.setEnd(...b);const s=window.getSelection();s.removeAllRanges();s.addRange(r);}
function snapshot(label='Undo edit'){const c=chat();c.undo.push({draft:c.draft,kept:[...c.kept],label});if(c.undo.length>100)c.undo.shift();c.redo=[];}
function preserveKeep(before,after,kept,changes){const old=C.detect(before,state.prefs.categories),next=C.detect(after,state.prefs.categories);return old.filter(f=>kept.includes(f.id)&&!changes.some(x=>x.start<f.end&&x.end>f.start)).map(f=>{const offset=changes.filter(x=>x.end<=f.start).reduce((n,x)=>n+x.value.length-(x.end-x.start),0);return next.find(x=>x.start===f.start+offset&&x.category===f.category&&x.value===f.value)?.id;}).filter(Boolean);}
function replaceFlags(flags,type='mask'){const c=chat(),before=c.draft,kept=[...c.kept],changes=flags.map(f=>({start:f.start,end:f.end,value:type==='generalise'?f.generalised:f.replacement})).sort((a,b)=>b.start-a.start);for(const x of changes)c.draft=c.draft.slice(0,x.start)+x.value+c.draft.slice(x.end);c.kept=preserveKeep(before,c.draft,kept,changes);}
function inputChanged(){if(composing)return;const el=$('#composer'),c=chat(),text=el.textContent.replace(/\r/g,'');if(text===c.draft)return;const now=Date.now();if(now-lastTyping>650||!c.undo.length){snapshot('Undo edit');S.event('draft_edited',{count:C.detect(text,state.prefs.categories).length});}lastTyping=now;let start=0,end=c.draft.length,nextEnd=text.length;while(start<end&&start<nextEnd&&c.draft[start]===text[start])start++;while(end>start&&nextEnd>start&&c.draft[end-1]===text[nextEnd-1]){end--;nextEnd--;}c.kept=preserveKeep(c.draft,text,c.kept,[{start,end,value:text.slice(start,nextEnd)}]);c.draft=text;save();renderComposer(true);}
function insertPlain(text){const el=$('#composer'),c=chat(),at=selectionOffsets(el)||[c.draft.length,c.draft.length];snapshot('Undo edit');const after=c.draft.slice(0,at[0])+text+c.draft.slice(at[1]);c.kept=preserveKeep(c.draft,after,c.kept,[{start:at[0],end:at[1],value:text}]);c.draft=after;lastTyping=0;save();S.event('draft_edited',{count:issues().length});renderComposer();el.focus();restoreSelection(el,[at[0]+text.length,at[0]+text.length]);}
function bindComposer(){const el=$('#composer');el.addEventListener('input',inputChanged);el.addEventListener('compositionstart',()=>composing=true);el.addEventListener('compositionend',()=>{composing=false;inputChanged();});el.addEventListener('paste',e=>{e.preventDefault();insertPlain(e.clipboardData.getData('text/plain').replace(/\r\n?/g,'\n'));});el.addEventListener('beforeinput',e=>{if(e.inputType==='insertParagraph'||e.inputType==='insertLineBreak'){e.preventDefault();insertPlain('\n');}});el.addEventListener('keydown',e=>{if(e.isComposing)return;if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();send();}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);}else if(e.target.dataset.flag&&e.key==='Enter'){e.preventDefault();openReview(e.target.dataset.flag,'inline');}});el.addEventListener('click',e=>{const f=e.target.closest('[data-flag]');if(f)openReview(f.dataset.flag,'inline');});}
function openReview(id,source='warning'){reviewOpen=true;selected=id||pending()[0]?.id||issues()[0]?.id;S.event('review_opened',{source,category:issues().find(f=>f.id===selected)?.category||'none',count:issues().length});renderReview();$('#review-title')?.focus();}
function changeIssue(id,type){const f=issues().find(f=>f.id===id);if(!f)return;snapshot(type==='keep'?'Undo keep decision':type==='unkeep'?'Undo review decision':type==='generalise'?'Undo generalisation':'Undo masking');const c=chat();lastTyping=0;if(type==='keep')c.kept.push(f.id);else if(type==='unkeep')c.kept=c.kept.filter(x=>x!==f.id);else{replaceFlags([f],type);if(type==='generalise'){const next=C.detect(c.draft,state.prefs.categories).find(x=>x.start===f.start&&x.value===f.generalised);if(next)c.kept.push(next.id);}}S.event(type==='keep'?'detail_kept':type==='unkeep'?'detail_reopened':'detail_replaced',{category:f.category,action:type});save();selected=pending()[0]?.id||null;renderComposer();toast(type==='keep'?'Detail kept unchanged. It will be shared when you send.':type==='unkeep'?'Detail is ready to review again.':'Draft updated. Review the wording before you send.','undo','Undo');$('#review-title')?.focus();}
function undo(redo=false){const c=chat(),from=redo?c.redo:c.undo,to=redo?c.undo:c.redo;if(!from.length)return;const old=from.pop();to.push({draft:c.draft,kept:[...c.kept],label:old.label});c.draft=old.draft;c.kept=old.kept;lastTyping=0;selected=null;S.event(redo?'draft_redone':'draft_undone');save();renderComposer();$('#composer')?.focus();announce(redo?'Change restored.':'Previous draft restored.');}
function example(id){const sc=C.scenarios[id];if(!sc)return;const load=()=>{closeModal();snapshot('Undo example');chat().draft=sc.prompt;chat().kept=[];reviewOpen=false;save();render();$('#composer').focus();S.event('example_loaded',{choice:id});};if(chat().draft.trim())modal('Replace this draft?', '<p>The fictional example will replace your current draft. Undo can restore it before you send.</p>',button('Cancel','close-modal')+button('Load example','confirm-example','primary',`data-id="${id}"`));else load();}
function send(override=false){const c=chat(),text=c.draft.trim();if(!text)return;const unreviewed=pending();if(state.prefs.warningMode==='pause'&&unreviewed.length&&!override){S.event('send_paused',{count:unreviewed.length});modal('Review before sending?',`<p>This prompt still has ${unreviewed.length} unreviewed detail${unreviewed.length===1?'':'s'}. You can review the suggestions or deliberately send the current wording.</p>`,button('Back to draft','close-modal')+button('Send unchanged','send-anyway')+button('Review details','modal-review','primary'));return;}const all=issues();S.event('prompt_sent',{count:all.length,retainedCount:all.length-unreviewed.length,unreviewedCount:unreviewed.length,action:override?'explicit_override':'send'});const originalCount=c.messages.length;c.messages.push({role:'user',text});if(!originalCount)c.title=/401|403|API/i.test(text)?'Debugging a request':/Punggol|nearby/i.test(text)?'Local recommendations':/leak|message/i.test(text)?'Drafting a message':'Conversation '+state.chats.length;for(const f of all){if(!state.items.some(x=>x.value===f.value&&x.chatId===c.id)){state.items.push({id:S.uid(),group:'shared',label:C.categories[f.category].singular,value:f.value,category:f.category,source:c.title,chatId:c.id,reuse:'default',explanation:'Detected by a simple rule in a message you sent in this prototype. The entry is a local demonstration record, not actual GPT memory.'});}}
 c.messages.push({role:'assistant',text:C.response(text,c.messages)});c.draft='';c.kept=[];c.undo=[];c.redo=[];reviewOpen=false;selected=null;save();closeModal();const a=activeTrial();if(a?.startedAt){const sc=C.scenarios[a.scenario];if(['mask','retain','multiple','followup'].includes(sc?.family)){let success=false;if(sc.family==='mask')success=!C.detect(text).some(f=>f.category==='credential')&&/401|403|error|request|debug/i.test(text);if(sc.family==='retain')success=/Punggol/i.test(text);if(sc.family==='multiple')success=!C.detect(text).some(f=>['name','email','phone'].includes(f.category))&&/leak/i.test(text);if(sc.family==='followup')success=originalCount>=2;S.finish(success,'prompt_sent');}}
 hideToast();render();document.querySelectorAll('.messages .message').forEach((m,i)=>{if(i>=originalCount)m.classList.add('is-new');});const convo=$('.conversation');if(convo)convo.scrollTop=convo.scrollHeight;$('#composer').focus();announce('Message sent. A scripted response is ready.');}
function batch(){const flags=pending();modal('Review multiple changes',`<p>Select the replacements you want to apply. Unselected details remain in your draft.</p>${flags.map(f=>`<label class="batch-item"><input type="checkbox" name="batch" value="${f.id}" checked><span><strong>${esc(C.categories[f.category].singular)}</strong><span class="value">${esc(f.value)} → ${esc(f.replacement)}</span></span></label>`).join('')}`,button('Cancel','close-modal')+button('Apply selected changes','apply-batch','primary'));}
function applyBatch(){const ids=[...document.querySelectorAll('input[name=batch]:checked')].map(x=>x.value),flags=pending().filter(x=>ids.includes(x.id));if(!flags.length){toast('Select at least one replacement.');return;}snapshot('Undo masking');replaceFlags(flags);S.event('batch_replaced',{count:flags.length});save();closeModal();selected=null;renderComposer();toast(`${flags.length} replacements applied to the draft.`,'undo','Undo');}
function memoryDetails(id){const x=state.items.find(x=>x.id===id);if(!x)return;S.event('profile_details_opened',{category:x.category});modal('Information details',`<span class="badge">${esc(groupLabels[x.group])}</span><p class="detail-value">${esc(x.value)}</p><p>${esc(x.explanation)}</p><p><strong>Source:</strong> ${esc(x.source)}</p>${x.group==='inferences'?'<div class="info-banner warning">An unconfirmed fictional inference, not a fact about you.</div>':''}<label class="field">Correct this profile value<input id="memory-edit" value="${esc(x.value)}" maxlength="180"><small>This edits the profile entry; the source message stays unchanged.</small></label><label class="field">Use in another conversation<select id="memory-reuse">${Object.entries(reuseLabels).map(([v,l])=>`<option value="${v}" ${x.reuse===v?'selected':''}>${l}</option>`).join('')}</select></label>`,button('Cancel','close-modal')+button('Delete item','delete-item','text-danger',`data-id="${id}"`)+button('Save changes','save-item','primary',`data-id="${id}"`));}
function deletion(id,permanent=false){const x=(permanent?state.removed:state.items).find(x=>x.id===id);if(!x)return;modal(permanent?'Permanently delete this profile copy?':'Delete this profile item?',`<p class="detail-value">${esc(x.value)}</p><ul class="scope-list"><li>${icon('trash')}${permanent?'Erases the recoverable profile copy from this browser. This cannot be undone.':'Moves this item to Removed and stops its simulated future reuse.'}</li><li>${icon('chat')}The original conversation and its text remain unchanged.</li><li>${icon('lock')}Anonymous study events and previously exported files remain. Actual GPT data is unaffected.</li>${permanent?'':`<li>${icon('undo')}You can restore it from Removed until you choose Delete permanently.</li>`}</ul>`,button('Cancel','close-modal')+button(icon('trash','small')+(permanent?'Delete permanently':'Delete'),'confirm-delete','danger',`data-id="${id}" data-permanent="${permanent}"`));}
function confirmDelete(id,permanent){const list=permanent?state.removed:state.items;if(list.findIndex(x=>x.id===id)<0)return;closeModal();collapseCard(id,()=>finishDelete(id,permanent));}
function finishDelete(id,permanent){const list=permanent?state.removed:state.items,index=list.findIndex(x=>x.id===id);if(index<0)return;const [x]=list.splice(index,1);if(!permanent){state.removed.unshift(x);state.lastUndoRemoval=id;}else if(state.lastUndoRemoval===id)state.lastUndoRemoval=null;S.event(permanent?'profile_permanently_deleted':'profile_deleted',{category:x.category});save();render();toast(permanent?'Recoverable profile copy deleted. Original chat text remains.':'Item removed from the active profile. Original chat text remains.',permanent?null:'undo-removal',permanent?null:'Undo');}
let deletedChat=null;
function chatDeletion(id){const c=state.chats.find(c=>c.id===id);if(!c)return;const n=c.messages.length;modal('Delete this conversation?',`<p class="detail-value">${esc(c.title)}</p><ul class="scope-list"><li>${icon('trash')}Removes ${n?`its ${n} message${n===1?'':'s'}`:'this conversation'}${c.draft.trim()?' and the unsent draft':''} from this browser.</li><li>${icon('shield')}Information already in your privacy dashboard stays there. Delete it from the dashboard if you no longer want it reused.</li><li>${icon('lock')}Anonymous study events and previously exported files remain. Actual GPT data is unaffected.</li><li>${icon('undo')}You can undo this right after deleting.</li></ul>`,button('Cancel','close-modal')+button(icon('trash','small')+'Delete conversation','confirm-delete-chat','danger',`data-id="${esc(id)}"`));}
function confirmDeleteChat(id){const index=state.chats.findIndex(c=>c.id===id);if(index<0)return;const wasCurrent=chat().id===id;const [c]=state.chats.splice(index,1);let placeholder=null;if(!state.chats.length){const b=C.blankChat(S.uid());state.chats.push(b);placeholder=b.id;}if(wasCurrent)state.currentChat=state.chats[0].id;deletedChat={chat:c,index,wasCurrent,placeholder};S.event('conversation_deleted',{count:c.messages.length});save();render();modalReturn=$('#navigation .chat-link')||$('.mobile-menu');closeModal();toast('Conversation deleted.','undo-chat-delete','Undo');}
function undoChatDelete(){if(!deletedChat)return;const {chat:c,index,wasCurrent,placeholder}=deletedChat;deletedChat=null;const p=state.chats.find(x=>x.id===placeholder);if(p&&!p.messages.length&&!p.draft.trim())state.chats=state.chats.filter(x=>x!==p);state.chats.splice(Math.min(index,state.chats.length),0,c);if(wasCurrent)state.currentChat=c.id;S.event('conversation_restored');save();hideToast();render();announce('Conversation restored.');}
function restore(id){if(state.removed.findIndex(x=>x.id===id)<0)return;collapseCard(id,()=>{const i=state.removed.findIndex(x=>x.id===id);if(i<0)return;const [x]=state.removed.splice(i,1);state.items.push(x);state.lastUndoRemoval=null;S.event('profile_restored',{category:x.category});save();render();toast('Profile item restored with its previous reuse setting.');});}
function updateFilter(){document.querySelectorAll('.tabs .tab').forEach(t=>{const on=t.dataset.id===filter;t.classList.toggle('active',on);t.setAttribute('aria-pressed',on);});placeIndicator();renderMemory(true);}
function placeIndicator(instant){const t=$('.tabs .tab.active'),ind=$('.tab-indicator');if(!t||!ind)return;if(instant)ind.style.transition='none';ind.style.transform=`translate(${t.offsetLeft}px,${t.offsetTop}px)`;ind.style.width=t.offsetWidth+'px';ind.style.height=t.offsetHeight+'px';if(instant){void ind.offsetWidth;ind.style.transition='';}}
function animateList(el,h0){el.querySelectorAll('.memory-card,.empty-state,.info-banner').forEach((c,i)=>{c.style.setProperty('--i',i);c.classList.add('card-in');});const h1=el.offsetHeight;if(Math.abs(h1-h0)<2)return;el.style.height=h0+'px';el.style.overflow='hidden';void el.offsetHeight;el.style.transition='height var(--dur-slow) var(--ease-out)';el.style.height=h1+'px';const done=()=>{el.style.height=el.style.overflow=el.style.transition='';};el.addEventListener('transitionend',done,{once:true});setTimeout(done,400);}
function collapseCard(id,done){const card=document.querySelector(`.memory-card [data-id="${CSS.escape(id)}"]`)?.closest('.memory-card');if(!card||reduced()){done();return;}card.style.height=card.offsetHeight+'px';void card.offsetHeight;card.classList.add('card-out');setTimeout(done,280);}
function capturePreferences(){const form=$('#preferences-form');if(!form)return;prefsDraft={warningMode:form.querySelector('[name=warningMode]:checked').value,reuseMode:form.querySelector('[name=reuseMode]:checked').value,display:form.querySelector('[name=display]:checked')?.value||'standard',categories:Object.fromEntries([...form.querySelectorAll('[name=category]')].map(x=>[x.value,x.checked]))};state.prefsDraft=C.clone(prefsDraft);save();applyDisplay(prefsDraft.display);$('#preference-save-status').textContent='Unsaved changes · your choices are preserved if you navigate away.';}
function bindPreferences(){$('#preferences-form').addEventListener('change',capturePreferences);$('#preferences-form').addEventListener('submit',e=>{e.preventDefault();capturePreferences();state.prefs=C.clone(prefsDraft);delete state.prefsDraft;save();S.event('preferences_saved',{choice:state.prefs.reuseMode,action:state.prefs.warningMode,disabledCount:Object.values(state.prefs.categories).filter(v=>!v).length});$('#preference-save-status').textContent='Preferences saved in this browser.';toast('Privacy preferences saved.');});}
function reuseDemo(){const list=state.items.filter(x=>x.group!=='inferences');if(!list.length){toast('No active profile items are available. Restore an item to try reuse.');return;}modal('Try simulated reuse',`<p>This example starts a separate pretend conversation. Select an active profile item to see how your saved rules apply.</p><label class="field">Profile item<select id="demo-item">${list.map(x=>`<option value="${x.id}">${esc(x.label)} — ${esc(x.value)}</option>`).join('')}</select></label><p>Save preference changes before running this example. Individual item rules take priority over the default.</p><div id="reuse-result" aria-live="polite"></div>`,button('Close','close-modal')+button('Run example','run-reuse','primary'));}
function runReuse(){const x=state.items.find(x=>x.id===$('#demo-item')?.value);if(!x)return;let mode=x.reuse==='default'?state.prefs.reuseMode:x.reuse;S.event('reuse_example_started',{category:x.category,choice:mode});if(mode==='ask'){modal('Allow this detail for this example?',`<p>The scripted example wants to use:</p><p class="detail-value">${esc(x.value)}</p><p>Permission applies to this example once. Your saved preference will stay the same.</p>`,button('Do not use','reuse-answer','',`data-id="${x.id}" data-allow="false"`)+button('Use for this example','reuse-answer','primary',`data-id="${x.id}" data-allow="true"`));}else showReuseResult(x,mode==='auto',mode);}
function showReuseResult(x,allow,mode){S.event('reuse_decided',{category:x.category,choice:allow?'allow':'decline'});modal('Simulated reuse result',`<span class="badge ${allow?'purple':''}">${allow?'Used for this example':'Not used in this example'}</span><div class="reuse-preview"><p>${allow?`This scripted preview used “${esc(x.value)}” as context. ${x.category==='location'?'A neighbourhood could help tailor an example plan.':'This can illustrate a personalised answer.'}`:'This scripted preview uses only the current request. No earlier profile information was included.'}</p></div><p class="preferences-note">Rule: ${esc(reuseLabels[mode]||'Only approved details')}. This is a local preview; no data was sent to a model.</p>`,button('Close','close-modal')+button('Try another','reuse-demo','primary'));}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;switch(a){
 case 'toggle-theme':setTheme(!isDark());$('.theme-toggle')?.focus();announce(isDark()?'Dark mode on':'Dark mode off');break;
 case 'toggle-menu':setSidebar(!sidebarOpen);if(sidebarOpen)$('#navigation .new-chat').focus();break;
 case 'close-menu':setSidebar(false);$('.mobile-menu')?.focus();break;
 case 'new-chat':{const c=C.blankChat(S.uid());state.chats.unshift(c);state.currentChat=c.id;save();navigate('chat');render();$('#composer')?.focus();break;}
 case 'open-chat':case 'source':state.currentChat=id;save();S.event('conversation_opened',{source:a==='source'?'profile':'navigation'});navigate('chat');render();break;
 case 'example':example(id);break;
 case 'confirm-example':snapshot('Undo example');chat().draft=C.scenarios[id].prompt;chat().kept=[];save();closeModal();render();$('#composer').focus();break;
 case 'review':openReview(null);break;
 case 'select-issue':selected=id;S.event('detail_selected',{category:issues().find(x=>x.id===id)?.category||'none'});renderReview();$('#review-title').focus();break;
 case 'close-review':reviewOpen=false;renderReview();$('#review-button')?.focus();break;
 case 'edit-draft':reviewOpen=false;renderReview();$('#composer').focus();break;
 case 'mask':case 'generalise':case 'keep':case 'unkeep':changeIssue(id,a);break;
 case 'undo':undo();break;case 'redo':undo(true);break;
 case 'send':send();break;case 'send-anyway':send(true);break;
 case 'modal-review':closeModal();openReview();break;
 case 'batch':batch();break;case 'apply-batch':applyBatch();break;
 case 'filter':if(filter===id)break;filter=id;S.event('profile_filter_changed',{choice:id});updateFilter();break;
 case 'memory-details':memoryDetails(id);break;
 case 'save-item':{const x=state.items.find(x=>x.id===id),value=$('#memory-edit').value.trim();if(!value){$('#memory-edit').setCustomValidity('Enter a value.');$('#memory-edit').reportValidity();return;}x.value=value;x.reuse=$('#memory-reuse').value;S.event('profile_updated',{category:x.category,choice:x.reuse});save();closeModal();render();toast('Profile item updated. Original chat text is unchanged.');break;}
 case 'delete-item':deletion(id);break;case 'permanent':deletion(id,true);break;
 case 'confirm-delete':confirmDelete(id,b.dataset.permanent==='true');break;
 case 'delete-chat':chatDeletion(id);break;case 'confirm-delete-chat':confirmDeleteChat(id);break;case 'undo-chat-delete':undoChatDelete();break;
 case 'restore':restore(id);break;case 'undo-removal':restore(state.lastUndoRemoval);break;
 case 'apply-default':modal('Use the default for existing items?', '<p>All active profile items except possible inferences will be set to “Follow default.” This replaces their individual reuse rules. Save your preference first if you have changed it.</p>',button('Cancel','close-modal')+button('Apply saved default','confirm-default','primary'));break;
 case 'confirm-default':state.items.filter(x=>x.group!=='inferences').forEach(x=>x.reuse='default');save();S.event('default_applied_to_items',{count:state.items.length});closeModal();toast('Active items now follow your saved default.');break;
 case 'reuse-demo':reuseDemo();break;case 'run-reuse':runReuse();break;
 case 'reuse-answer':{const x=state.items.find(x=>x.id===id);if(x)showReuseResult(x,b.dataset.allow==='true','ask');break;}
 case 'close-modal':closeModal();break;case 'dismiss-toast':hideToast();break;
 case 'begin-task':if(S.start()){render();$('#composer')?.focus();announce('Task started.');}break;
 case 'finish-task':if(S.finish()){render();toast('Task finished. Please return to the researcher.');}break;
}});
document.addEventListener('input',e=>{if(e.target.id==='memory-search'){search=e.target.value;renderMemory();}if(e.target.id==='memory-edit')e.target.setCustomValidity('');});
document.addEventListener('keydown',e=>{if(e.altKey&&e.key.toLowerCase()==='r'&&route==='chat'){e.preventDefault();openReview();}if(e.key==='Escape'&&!$('#modal').open){if(widgetOpen){setWidgetOpen(false);$('.nav-fab').focus();}else if(reviewOpen){reviewOpen=false;renderReview();$('#review-button')?.focus();}else if(sidebarOpen){setSidebar(false);$('.mobile-menu')?.focus();}}});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
$('#nav-widget').addEventListener('pointerdown',e=>{const f=e.target.closest('.nav-fab');if(!f||e.button!==0)return;drag={id:e.pointerId,sx:e.clientX,sy:e.clientY,ox:widgetPos.x,oy:widgetPos.y,moved:false};f.setPointerCapture(e.pointerId);});
$('#nav-widget').addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.sx,dy=e.clientY-drag.sy;if(!drag.moved&&Math.hypot(dx,dy)<5)return;if(!drag.moved){drag.moved=true;setWidgetOpen(false);$('#nav-widget').classList.add('dragging');}widgetPos={x:drag.ox+dx,y:drag.oy+dy};if(!dragFrame)dragFrame=requestAnimationFrame(()=>{dragFrame=0;placeWidget();});});
$('#nav-widget').addEventListener('pointerup',e=>{if(!drag||e.pointerId!==drag.id)return;const moved=drag.moved,w=$('#nav-widget');drag=null;cancelAnimationFrame(dragFrame);dragFrame=0;w.classList.remove('dragging');if(moved){widgetPos.x=widgetPos.x+FAB/2>innerWidth/2?innerWidth-FAB-EDGE:EDGE;w.classList.add('snapping');placeWidget();setTimeout(()=>w.classList.remove('snapping'),350);saveWidgetPos();}else setWidgetOpen(!widgetOpen);});
$('#nav-widget').addEventListener('pointercancel',()=>{drag=null;cancelAnimationFrame(dragFrame);dragFrame=0;$('#nav-widget').classList.remove('dragging');});
$('#nav-widget').addEventListener('keydown',e=>{const items=[...document.querySelectorAll('#nav-widget-menu [role=menuitem]')],i=items.indexOf(document.activeElement);if(e.target.classList.contains('nav-fab')){if(e.altKey&&e.key.startsWith('Arrow')){e.preventDefault();e.stopPropagation();const d=e.shiftKey?60:20;widgetPos={x:widgetPos.x+(e.key==='ArrowLeft'?-d:e.key==='ArrowRight'?d:0),y:widgetPos.y+(e.key==='ArrowUp'?-d:e.key==='ArrowDown'?d:0)};placeWidget();saveWidgetPos();}else if(['Enter',' ','ArrowDown'].includes(e.key)){e.preventDefault();setWidgetOpen(true,true);}else if(e.key==='ArrowUp'){e.preventDefault();setWidgetOpen(true);items.at(-1)?.focus();}}else if(i>-1){if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();items[(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length].focus();}else if(e.key==='Home'||e.key==='End'){e.preventDefault();items[e.key==='Home'?0:items.length-1].focus();}else if(e.key===' '){e.preventDefault();items[i].click();}else if(e.key==='Tab')setWidgetOpen(false);}});
$('#nav-widget').addEventListener('click',e=>{if(e.target.closest('[role=menuitem]')){const h=e.target.closest('[role=menuitem]').getAttribute('href');widgetOpen=false;if(location.hash===h){e.preventDefault();render();}}});
document.addEventListener('pointerdown',e=>{if(widgetOpen&&!e.target.closest('#nav-widget'))setWidgetOpen(false);});
matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',e=>{let saved=null;try{saved=localStorage.getItem(THEME_KEY);}catch{}if(!saved)setTheme(e.matches,false);});
window.addEventListener('resize',()=>{placeWidget();placeIndicator(true);});
window.addEventListener('hashchange',()=>{sidebarOpen=false;render();S.event('screen_opened',{screen:route});$('#main h1')?.focus();});
window.addEventListener('storage',e=>{if([S.STATE,S.STUDY].includes(e.key)){state=S.state();const a=activeTrial();if(a&&!a.startedAt){prefsDraft=null;reviewOpen=false;selected=null;if(route!=='chat'){location.hash='chat';return;}}render();}});
window.addEventListener('clarity-storage-error',()=>announce('Browser storage failed. Changes may not survive a reload.'));
render();
})();
